def caesar(s, k):
    def shift(char, base):
        return chr((ord(char) - base + k % 26) % 26 + base)

    result = []
    for char in s:
        if char.isalpha():
            if char.islower():
                result.append(shift(char, ord('a')))
            else:
                result.append(shift(char, ord('A')))
        else:
            result.append(char)
    return ''.join(result)
```

