def bsearch(xs, t):
    lo = 0
    hi = len(xs) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if xs[mid] < t:
            lo = mid + 1
        elif xs[mid] > t:
            hi = mid - 1
        else:
            # Found t at mid; check if there is a smaller index
            if mid == 0 or xs[mid - 1] > t:
                return mid
            else:
                # There is a smaller index with t, so continue searching left
                hi = mid - 1
    return -1
```

